    country_code character(2),
    city character varying(80),
    language_code character varying(10),
    status_code character varying(30) NOT NULL,
    rating_classical integer DEFAULT 1200 NOT NULL,
    rating_rapid integer DEFAULT 1200 NOT NULL,
    rating_blitz integer DEFAULT 1200 NOT NULL,
    birth_date date,
    registration_date date NOT NULL,
    CONSTRAINT chk_birth_before_registration CHECK (((birth_date IS NULL) OR (birth_date < registration_date))),
    CONSTRAINT player_rating_blitz_check CHECK ((rating_blitz >= 0)),
    CONSTRAINT player_rating_classical_check CHECK ((rating_classical >= 0)),
    CONSTRAINT player_rating_rapid_check CHECK ((rating_rapid >= 0))
);


