    max_daily_games integer DEFAULT 0 NOT NULL,
    has_analytics boolean DEFAULT false NOT NULL,
    has_puzzles boolean DEFAULT false NOT NULL,
    has_engine boolean DEFAULT false NOT NULL,
    description character varying(500),
    CONSTRAINT chk_annual_gte_monthly CHECK ((price_annual >= price_monthly)),
    CONSTRAINT subscription_tier_max_daily_games_check CHECK ((max_daily_games >= 0)),
    CONSTRAINT subscription_tier_price_annual_check CHECK ((price_annual >= (0)::numeric)),
    CONSTRAINT subscription_tier_price_monthly_check CHECK ((price_monthly >= (0)::numeric))
);


