    release_date date NOT NULL,
    client_type character varying(20),
    domain_url character varying(255),
    browser_engine character varying(50),
    app_store_url character varying(255),
    android_version character varying(50),
    CONSTRAINT uiclient_client_type_check CHECK (((client_type)::text = ANY (ARRAY[('Web'::character varying)::text, ('Mobile'::character varying)::text])))
);


--
-- Name: vw_client_login_activity; Type: VIEW; Schema: public; Owner: -
--

CREATE VIEW public.vw_client_login_activity AS
 SELECT u.client_id,
    u.name AS client_name,
    u.client_type,
    count(ll.log_id) AS total_logins,
    count(DISTINCT ll.player_id) AS distinct_players,
    count(DISTINCT p.country_code) AS player_countries,
    sum(
        CASE
            WHEN ll.is_suspicious THEN 1
            ELSE 0
        END) AS suspicious_logins,
    max(ll.login_date) AS last_login_date
   FROM ((public.uiclient u
     LEFT JOIN public.login_log ll ON ((ll.client_id = u.client_id)))
     LEFT JOIN public.player p ON ((p.player_id = ll.player_id)))
  GROUP BY u.client_id, u.name, u.client_type;


--
-- Name: vw_engine_overview; Type: VIEW; Schema: public; Owner: -
--

CREATE VIEW public.vw_engine_overview AS
 WITH bot_counts AS (
         SELECT bot.engine_id,
            count(*) AS bot_count
           FROM public.bot
          GROUP BY bot.engine_id
        ), eval_stats AS (
         SELECT engineevaluation.engine_id,
            count(*) AS evaluation_count,
            round(avg(engineevaluation.search_depth), 1) AS avg_search_depth
           FROM public.engineevaluation
          GROUP BY engineevaluation.engine_id
        )
 SELECT e.engine_id,
    e.name AS engine_name,
    e.version,
        CASE
            WHEN (le.engine_id IS NOT NULL) THEN 'Local'::text
            WHEN (ce.engine_id IS NOT NULL) THEN 'Cloud'::text
            ELSE 'Generic'::text
        END AS engine_type,
    COALESCE(bc.bot_count, (0)::bigint) AS bot_count,
    COALESCE(es.evaluation_count, (0)::bigint) AS evaluation_count,
    es.avg_search_depth
   FROM ((((public.engine e
     LEFT JOIN public.localengine le ON ((le.engine_id = e.engine_id)))
     LEFT JOIN public.cloudengine ce ON ((ce.engine_id = e.engine_id)))
     LEFT JOIN bot_counts bc ON ((bc.engine_id = e.engine_id)))
     LEFT JOIN eval_stats es ON ((es.engine_id = e.engine_id)));


--
-- Name: vw_player_club_membership; Type: VIEW; Schema: public; Owner: -
--

CREATE VIEW public.vw_player_club_membership AS
 SELECT p.player_id,
    p.username,
    (((p.first_name)::text || ' '::text) || (p.last_name)::text) AS full_name,
    p.country_code,
    p.rating_classical,
    p.status_code AS player_status,
    c.club_id,
    c.club_name,
    c.is_official,
    cm.role_code,
    cm.join_date
   FROM ((public.player p
     JOIN public.club_membership cm ON (((cm.player_id = p.player_id) AND ((cm.status_code)::text = 'active'::text))))
     JOIN public.club c ON ((c.club_id = cm.club_id)));


